code.cpp:
class Solution {
public:
    int numFriendRequests(vector<int>& ages) {
        int count[121] = {0};
        for (int a : ages) count[a]++;
        long long res = 0;
        for (int x = 1; x <= 120; x++) {
            if (count[x] == 0) continue;
            for (int y = 1; y <= 120; y++) {
                if (count[y] == 0) continue;
                if (2 * y <= x + 14) continue;
                if (y > x) continue;
                if (x != y) {
                    res += (long long)count[x] * count[y];
                } else {
                    res += (long long)count[x] * (count[x] - 1);
                }
            }
        }
        return (int)res;
    }
};
